            <IconTrendingUp size={96} color={COLORS.mintGreen} />
            <div style={{ fontSize: 48, fontWeight: 800, color: COLORS.white }}>Track Landscape Shifts</div>
            <div style={{ fontSize: 36, color: COLORS.textMuted, lineHeight: 1.5 }}>
              Build an ongoing view of how your competitive landscape is shifting
            </div>
          </div>
        </div>

        <div style={{
          opacity: badgeProgress,
          transform: `scale(${interpolate(badgeProgress, [0, 1], [0.85, 1])})`,
          backgroundColor: "rgba(82,183,136,0.12)",
