};

// ─── Scene durations (raw, without transition overlap) ────────────────────────
// Each scene duration matches the script segment frame count
const D1  = 120;   // 00:00:00 → 00:04:20
const D2  =  75;   // 00:04:20 → 00:07:20
const D3  = 128;   // 00:08:00 → 00:13:02
const D4  = 206;   // 00:13:23 → 00:22:09
const D5  = 258;   // 00:23:06 → 00:33:17
const D6  = 222;   // 00:34:08 → 00:43:02
const D7  = 248;   // 00:43:20 → 00:53:12
const D8  = 321;   // 00:53:20 → 01:06:09
const D9  = 425;   // 01:07:03 → 01:24:01
const D10 = 410;   // 01:24:20 → 01:41:03
const D11 = 325;   // 01:41:03 → 01:54:01
const D12 = 251;   // 01:54:03 → 02:04:05
const D13 = 309;   // 02:04:05 → 02:16:12

const OPEN  = 20;
const CLOSE = 25;

// Total = OPEN + (all scene durations + TRANSITION each) + CLOSE
//         minus all transition overlaps (14 transitions total: open_fade + 12 between scenes + close_fade)
// TransitionSeries handles overlap automatically — durationInFrames is the
// sum of all Sequence durationInFrames values minus the sum of all transition durationInFrames.
// Sequences are given D + TRANSITION so the overlap is consumed by the transition.

const scenes = [D1,D2,D3,D4,D5,D6,D7,D8,D9,D10,D11,D12,D13];
const OPEN_TRANS = 20;
const numTransitions = scenes.length + 1; // open + between each scene + close

export const durationInFrames =
  OPEN +
  scenes.reduce((a, d) => a + d + TRANSITION, 0) +
  CLOSE -
  TRANSITION * numTransitions -
  OPEN_TRANS;

// ─── Main Composition ─────────────────────────────────────────────────────────
const MainComposition: React.FC = () => {
  const sceneComponents = [
    Scene1, Scene2, Scene3, Scene4, Scene5, Scene6, Scene7,
    Scene8, Scene9, Scene10, Scene11, Scene12, Scene13,
  ];
  const durations = scenes;

  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={OPEN}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: OPEN_TRANS })}
      />

      {sceneComponents.map((SceneComp, i) => (
        <React.Fragment key={i}>
          <TransitionSeries.Sequence durationInFrames={durations[i] + TRANSITION}>
            <SceneComp />
          </TransitionSeries.Sequence>
          <TransitionSeries.Transition
            presentation={fade()}
            timing={linearTiming({ durationInFrames: TRANSITION })}
          />
        </React.Fragment>
      ))}

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={CLOSE}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
